"""Reproduce REPA teaching diagrams; numerical evidence transcribed from course Tables 2/3."""
from pathlib import Path
from html import escape
out = Path(__file__).resolve().parents[1] / 'public/figures/repa'
out.mkdir(parents=True, exist_ok=True)
def text(x,y,s,size=19):
    return f'<text x="{x}" y="{y}" font-size="{size}">{escape(s)}</text>'
def box(x,y,w,title,sub,color='#ddd9fa'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="86" rx="12" fill="{color}" stroke="#71849a"/>'+text(x+14,y+32,title)+text(x+14,y+61,sub,16)
def arrow(x,y,a,b):
    return f'<path d="M{x},{y} L{a},{b}" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'
def svg(name,title,desc,body,h=430):
    (out/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 940 {h}" role="img" aria-labelledby="t d"><title id="t">{escape(title)}</title><desc id="d">{escape(desc)}</desc><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#53677d"/></marker></defs><rect width="940" height="{h}" rx="18" fill="#f3f6fb"/><g font-family="Arial,sans-serif" fill="#17304b">'+text(28,43,title,25)+body+'</g></svg>')
svg('problem','01 / Give early features a teacher','Schematic contrast of ordinary generation training and an auxiliary clean feature target.',box(30,90,255,'Noisy latent','Same input in both routes')+arrow(295,133,330,133)+box(340,90,265,'Learn useful features','Original generation loss')+arrow(615,133,650,133)+box(660,90,250,'Predict velocity','Semantics AND details')+box(30,245,255,'Clean training image','Extra training branch','#d4eee7')+arrow(295,288,330,288)+box(340,245,265,'Frozen visual teacher','Semantic feature targets','#d4eee7')+arrow(470,240,470,188)+text(620,290,'REPA: help the early layers',18)+text(30,380,'Green = frozen clean branch    Purple = learned generator    Orange = loss',18))
svg('training','02 / Training: generation + representation alignment','A clean image branches into VAE latent corruption and a clean visual teacher; projected early features get alignment supervision.',box(30,80,250,'A · Clean image x*','256 × 256 × 3','#d4eee7')+arrow(290,123,325,123)+box(335,80,260,'B · Frozen VAE E','z: 32 × 32 × 4','#d4eee7')+arrow(605,123,640,123)+box(650,80,260,'C · Add noise at t','zₜ = (1 − t)z + tε')+arrow(780,170,780,220)+box(650,235,260,'D · Early SiT blocks','hₜ: 256 × 1152; t, c')+arrow(780,330,780,380)+box(650,390,260,'Remaining blocks','E · velocity → loss','#ffe6cb')+box(335,235,260,'Trainable MLP hφ','p: 256 × D')+arrow(642,278,603,278)+box(30,235,250,'Frozen teacher f','y*: 256 × D','#d4eee7')+arrow(155,175,155,225)+box(185,390,330,'F · Patch alignment loss','Compare p with clean target y*','#ffe6cb')+arrow(155,330,275,380)+arrow(465,330,415,380)+text(30,535,'Both losses update the generator; only alignment updates the projection.',18)+text(30,567,'Teacher and VAE are fixed. Attach the projection at depth 8 for this XL setup.',18),610)
body=''
for j,x in enumerate([55,485]):
    body+=text(x,96,['Projected noisy features p','Clean teacher features y*'][j],21)
    for i in range(4):
        xx=x+(i%2)*170; yy=125+(i//2)*95
        body+=box(xx,yy,145,f'Patch {i+1}','D numbers',['#ddd9fa','#d4eee7'][j])
body+=arrow(380,213,470,213)+text(35,363,'Compare matching patch positions, then average their similarities.',19)+text(35,398,'Cosine compares feature direction, not magnitude. Four-patch teaching grid.',17)
svg('patches','03 / Alignment is spatial and feature-wise','Four illustrative corresponding patch features, compared by cosine direction.',body)
svg('numbers','04 / A complete toy loss calculation','The velocity squared error is 1 and negative cosine alignment is minus 0.8; lambda 0.5 gives combined loss 0.6.',box(30,95,270,'B → C · Make noisy latent','z = 2, ε = 6, t = 0.25')+arrow(310,137,345,137)+box(355,95,250,'zₜ = 3','Target velocity = 4')+arrow(615,137,650,137)+box(660,95,250,'E · Predict 3','Velocity error² = 1','#ffe6cb')+box(30,245,320,'D → F · Projected p = (3, 4)','Teacher y* = (0, 2)','#d4eee7')+arrow(360,288,395,288)+box(405,245,250,'Cosine = 0.8','REPA loss = −0.8','#ffe6cb')+arrow(665,288,700,288)+box(710,245,200,'Total = 0.6','1 + 0.5 × (−0.8)','#ffe6cb')+text(30,392,'Synthetic numbers: a smaller combined loss need not mean smaller velocity error.',18))
svg('sampling','05 / Inference: evolve a latent, with fixed weights','Noise enters the trained transformer and numerical sampler repeatedly; the final latent is decoded by the VAE.',box(30,110,260,'Start: Gaussian z₁','Choose class condition c')+arrow(300,153,335,153)+box(345,110,250,'Trained transformer','Predict vθ(zₜ, t, c)')+arrow(605,153,640,153)+box(650,110,260,'Numerical sampler','Update state and time')+f'<path d="M780 205 L780 260 L470 260 L470 205" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'+text(505,294,'Carry the new latent into the next call',17)+box(345,340,330,'End: VAE decoder → image','No teacher or projection needed','#d4eee7')+f'<path d="M880 205 L880 383 L690 383" stroke="#53677d" stroke-width="3" fill="none" marker-end="url(#a)"/>'+text(30,480,'Direction: t = 1 → 0. REPA changes training, not the sampling loop.',19),520)
svg('depth','06 / More classification accuracy is not always better FID','Measured depth 8 versus depth 16 ablation plus schematic early-to-late transformer.',box(30,100,260,'Early blocks','Learn useful representations')+arrow(300,143,335,143)+box(345,100,250,'Alignment attachment','Where should it go?','#ffe6cb')+arrow(605,143,640,143)+box(650,100,260,'Later blocks','Produce denoising details')+box(80,245,350,'Depth 8: FID 10.0','Linear-probe accuracy 68.1%','#d4eee7')+box(495,245,350,'Depth 16: FID 12.1','Linear-probe accuracy 71.1%','#ffe6cb')+text(30,380,'Table 2: SiT-L/2 · 400K iterations · DINOv2-L · NT-Xent · λ = 0.5',17)+text(30,414,'FID: lower is better. Probe accuracy: higher is better. No guidance.',17),450)
body=text(30,85,'ImageNet 256 × 256 · no guidance · FID-50K ↓ · course Table 3',18)
for i,(label,v,color) in enumerate([('Vanilla · 400K',17.2,'#73859d'),('Vanilla · 7M',8.3,'#73859d'),('REPA · 400K',7.9,'#168373'),('REPA · 1M',6.4,'#168373'),('REPA · 4M',5.9,'#168373')]):
    y=115+i*58
    body+=text(30,y+25,label)+f'<rect x="255" y="{y}" width="{v*32}" height="35" rx="5" fill="{color}"/>'+text(270+v*32,y+25,str(v))
body+=text(255,445,'0',16)+text(575,445,'10',16)+text(884,445,'20',16)+text(30,489,'7M / 400K = 17.5× fewer training iterations; not an inference speed ratio.',18)
svg('results','07 / Better FID with fewer training iterations','Five bars show FID 17.2, 8.3, 7.9, 6.4, and 5.9 for the stated training budgets.',body,525)
